const store = $getWorkflowStaticData('global');
const seen = store.seen || [];
const out = [];
for (const item of $input.all()) {
  const id = item.json.messageId;
  if (seen.includes(id)) continue;
  seen.push(id);
  out.push(item);
}
store.seen = seen.slice(-300);
return out;

