const first = $input.first().json;
const raw = String(first.content ?? first.text ?? first.output ?? '');
let d = {};
try { d = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { d = {}; }
const amount = Number(String(d.amount ?? '').replace(/[^0-9.]/g, ''));
const dueDate = /^\d{4}-\d{2}-\d{2}$/.test(String(d.dueDate || '')) ? d.dueDate : '';
const missing = [];
if (!d.billName) missing.push('bill name');
if (!amount) missing.push('amount');
if (!dueDate) missing.push('due date');
const norm = $('Normalize WhatsApp Message').first().json;
return [{ json: {
  valid: missing.length === 0,
  missing: missing.join(', '),
  billName: d.billName || '',
  category: d.category || 'Other',
  amount: amount,
  dueDate: dueDate,
  invoiceNumber: d.invoiceNumber || '',
  billId: 'BILL' + String(Date.now()).slice(-6),
  from: norm.from
} }];

const p = $('Parse & Validate Invoice').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.BillName);
const dup = rows.some(r =>
  String(r.WhatsAppNumber) === String(p.from) &&
  String(r.BillName).toLowerCase() === String(p.billName).toLowerCase() &&
  Number(r.Amount) === Number(p.amount) &&
  String(r.DueDate).slice(0, 10) === p.dueDate
);
return [{ json: Object.assign({}, p, { isDuplicate: dup }) }];

