const todayStr = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const dn = (s) => { const p = s.split('-').map(Number); return Date.UTC(p[0], p[1] - 1, p[2]) / 86400000; };
const toIso = (v) => {
  const s = String(v || '').trim();
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return iso[1] + '-' + iso[2] + '-' + iso[3];
  const ind = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (ind) return ind[3] + '-' + ind[2] + '-' + ind[1];
  return '';
};
const optedIn = new Set(
  $('Fetch Users (Consent)').all().map(i => i.json)
    .filter(u => String(u.ConsentStatus || '').toLowerCase() === 'optedin')
    .map(u => String(u.WhatsAppNumber))
);
const out = [];
for (const item of $input.all()) {
  const b = item.json;
  if (!b.BillID || !b.WhatsAppNumber || !b.DueDate) continue;
  if (!optedIn.has(String(b.WhatsAppNumber))) continue;
  const due = toIso(b.DueDate);
  if (!due) continue;
  const days = dn(due) - dn(todayStr);
  const rd = String(b.ReminderDays || '7,3,1,0').split(',').map(x => Number(x.trim()));
  let type = '';
  let label = '';
  if (days < 0) { type = 'overdue'; label = 'OVERDUE by ' + Math.abs(days) + ' day(s)'; }
  else if (rd.includes(days)) {
    type = 'due_in_' + days + '_days';
    label = days === 0 ? 'due TODAY' : (days === 1 ? 'due TOMORROW' : 'due in ' + days + ' days');
  } else continue;
  if (toIso(b.LastReminderDate) === todayStr && String(b.LastReminderType) === type) continue;
  out.push({ json: { BillID: b.BillID, WhatsAppNumber: String(b.WhatsAppNumber), BillName: b.BillName, Amount: b.Amount, DueDate: due, Category: b.Category, reminderType: type, label: label, today: todayStr } });
}
return out;
